import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_over_depth(
    torch::Tensor x, torch::Tensor weight, torch::Tensor bias_opt,
    int64_t stride, int64_t padding, int64_t dilation, int64_t groups, bool has_bias);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void conv2d_over_depth_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ bias,
    float* __restrict__ y,
    int B, int Cin, int H, int W, int D,
    int Cout, int K, int stride, int pad, int dilation, int groups,
    int Hout, int Wout, int Dout,
    int Cin_g, int Cout_g,
    int in_tile_h, int in_tile_w,
    int cout_tile, int num_co_tiles)
{
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int wo = blockIdx.x * blockDim.x + tx;
    int ho = blockIdx.y * blockDim.y + ty;
    int zidx = blockIdx.z;
    int od = zidx % Dout;
    int tmp = zidx / Dout;
    int coTileIdx = tmp % num_co_tiles;
    int b = tmp / num_co_tiles;
    int co_base = coTileIdx * cout_tile;
    int g = co_base / Cout_g;
    int ci0 = g * Cin_g;
    int id = od * stride - pad; // kernel depth == 1, offset 0
    bool valid = (ho < Hout) && (wo < Wout);
    int h0 = blockIdx.y * (int)blockDim.y * stride - pad;
    int w0 = blockIdx.x * (int)blockDim.x * stride - pad;
    extern __shared__ float smem[];
    Tensor sX = make_tensor(make_smem_ptr(smem), make_shape(in_tile_h, in_tile_w), make_stride(in_tile_w, 1));
    Tensor gX = make_tensor(make_gmem_ptr(x), make_shape(B, Cin, H, W, D),
                             make_stride(Cin*H*W*D, H*W*D, W*D, D, 1));
    Tensor gW = make_tensor(make_gmem_ptr(w), make_shape(Cout, Cin_g, K, K, 1),
                             make_stride(Cin_g*K*K, K*K, K, 1, 1));
    Tensor gY = make_tensor(make_gmem_ptr(y), make_shape(B, Cout, Hout, Wout, Dout),
                             make_stride(Cout*Hout*Wout*Dout, Hout*Wout*Dout, Wout*Dout, Dout, 1));
    // Multiple output channels sharing the same (b, id) input tile are computed
    // cooperatively per CTA so the shared-memory staged input tile is reused
    // across 'cout_tile' output channels instead of being reloaded per-channel.
    const int MAX_COUT_TILE = 8;
    float acc[MAX_COUT_TILE];
    #pragma unroll
    for (int t = 0; t < MAX_COUT_TILE; ++t) acc[t] = 0.f;
    if (id >= 0 && id < D) {
        int tid = ty * blockDim.x + tx;
        int nthreads = blockDim.x * blockDim.y;
        int tile_elems = in_tile_h * in_tile_w;
        for (int ci = 0; ci < Cin_g; ++ci) {
            int c = ci0 + ci;
            for (int idx = tid; idx < tile_elems; idx += nthreads) {
                int sh = idx / in_tile_w;
                int sw = idx % in_tile_w;
                int hh = h0 + sh;
                int ww = w0 + sw;
                float val = 0.f;
                if (hh >= 0 && hh < H && ww >= 0 && ww < W) {
                    val = gX(b, c, hh, ww, id);
                }
                sX(sh, sw) = val;
            }
            __syncthreads();
            if (valid) {
                for (int co_off = 0; co_off < cout_tile; ++co_off) {
                    int co = co_base + co_off;
                    float local_acc = 0.f;
                    for (int kh = 0; kh < K; ++kh) {
                        int sh = ty * stride + kh * dilation;
                        for (int kw = 0; kw < K; ++kw) {
                            int sw = tx * stride + kw * dilation;
                            local_acc += gW(co, ci, kh, kw, 0) * sX(sh, sw);
                        }
                    }
                    acc[co_off] += local_acc;
                }
            }
            __syncthreads();
        }
    }
    if (valid) {
        for (int co_off = 0; co_off < cout_tile; ++co_off) {
            int co = co_base + co_off;
            float out_val = acc[co_off];
            if (bias != nullptr) out_val += bias[co];
            gY(b, co, ho, wo, od) = out_val;
        }
    }
}
torch::Tensor conv2d_over_depth(
    torch::Tensor x, torch::Tensor weight, torch::Tensor bias_opt,
    int64_t stride, int64_t padding, int64_t dilation, int64_t groups, bool has_bias)
{
    TORCH_CHECK(x.is_cuda() && weight.is_cuda(), "tensors must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "expect float32");
    TORCH_CHECK(x.dim() == 5, "x must be 5D (B,C,H,W,D)");
    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();
    int B   = (int)x_c.size(0);
    int Cin = (int)x_c.size(1);
    int H   = (int)x_c.size(2);
    int W   = (int)x_c.size(3);
    int D   = (int)x_c.size(4);
    int Cout = (int)w_c.size(0);
    int Cin_g = (int)w_c.size(1);
    int K = (int)w_c.size(2); // square kernel over H,W
    // w_c.size(3) == K, w_c.size(4) == 1
    int s = (int)stride;
    int p = (int)padding;
    int dil = (int)dilation;
    int gr = (int)groups;
    int Cout_g = Cout / gr;
    int Hout = (H + 2*p - dil*(K-1) - 1) / s + 1;
    int Wout = (W + 2*p - dil*(K-1) - 1) / s + 1;
    int Dout = (D + 2*p - dil*(1-1) - 1) / s + 1;
    TORCH_CHECK(Hout > 0 && Wout > 0 && Dout > 0, "invalid output size");
    auto y = torch::empty({B, Cout, Hout, Wout, Dout}, x_c.options());
    const int TILE = 16;
    dim3 block(TILE, TILE, 1);
    // Choose how many output channels are processed per CTA so the shared-memory
    // staged input tile (which does not depend on the output channel) is reused
    // across multiple output channels instead of being reloaded once per channel.
    const int MAX_COUT_TILE = 8;
    int cout_tile = 1;
    for (int cand = MAX_COUT_TILE; cand >= 1; --cand) {
        if (Cout_g % cand == 0) { cout_tile = cand; break; }
    }
    int num_co_tiles = Cout / cout_tile;
    dim3 grid((Wout + TILE - 1) / TILE, (Hout + TILE - 1) / TILE,
               (unsigned)((long long)B * num_co_tiles * Dout));
    int in_tile_h = (TILE - 1) * s + (K - 1) * dil + 1;
    int in_tile_w = (TILE - 1) * s + (K - 1) * dil + 1;
    size_t smem_bytes = (size_t)in_tile_h * (size_t)in_tile_w * sizeof(float);
    const float* bias_ptr = nullptr;
    torch::Tensor bias_c;
    if (has_bias) {
        bias_c = bias_opt.contiguous();
        bias_ptr = bias_c.data_ptr<float>();
    }
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    conv2d_over_depth_kernel<<<grid, block, smem_bytes, stream>>>(
        x_c.data_ptr<float>(), w_c.data_ptr<float>(), bias_ptr, y.data_ptr<float>(),
        B, Cin, H, W, D,
        Cout, K, s, p, dil, gr,
        Hout, Wout, Dout,
        Cin_g, Cout_g,
        in_tile_h, in_tile_w,
        cout_tile, num_co_tiles);
    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "conv2d_over_depth launch failed");
    return y;
}
"""

_include_dir = "/workspace/cutegen_test/cutegen/cutlass/include"

cute_ext = load_inline(
    name="cute_conv3d_asym_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_over_depth"],
    extra_cflags=["-O3", f"-I{_include_dir}"],
    extra_cuda_cflags=["-O3", f"-I{_include_dir}"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Performs a standard 3D convolution with kernel (kernel_size, kernel_size, 1)
    using a custom CUTE-based cooperative-tiled CUDA kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        # Keep an nn.Conv3d purely as a parameter container (weight/bias init identical
        # to the reference implementation); its forward is not used.
        self.conv3d = nn.Conv3d(in_channels, out_channels, (kernel_size, kernel_size, 1),
                                 stride=stride, padding=padding, dilation=dilation,
                                 groups=groups, bias=bias)
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.has_bias = bias
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda().contiguous().float()
        weight = self.conv3d.weight
        if self.has_bias:
            bias = self.conv3d.bias
        else:
            bias = torch.empty(0, device=x.device, dtype=x.dtype)
        return self._ext.conv2d_over_depth(
            x, weight, bias,
            self.stride, self.padding, self.dilation, self.groups, self.has_bias
        )

